import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate, Link } from "react-router-dom";
import './Login.css'; // Import the CSS file

function Login() {
    const history = useNavigate();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');

    async function submit(e) {
        e.preventDefault();

        try {
            const res = await axios.post("http://localhost:8000/", {
                email,
                password
            });

            if (res.data === "exist") {
                history("/home", { state: { id: email } });
                history(`/home?email=${encodeURIComponent(email)}`);
                //localStorage.setItem('email', email); // REMOVE this line
                localStorage.setItem('email', email);
                  // In Login.js after successful 
            } else if (res.data === "notexist") {
                alert("User has not signed up");
            }
        } catch (error) {
            alert("Wrong details");
            console.error(error);
        }
        navigate(`/profile/${email}`);
    }

    return (
        <div className="login">
            <section className="services-section">
        <h2>DigiBank</h2>
        <div className="services">
          <div className="service-card">
            <span className="icon">🐖</span>
            <h3>Savings Account</h3>
            <p>Grow your wealth securely with our high-interest savings accounts.</p>
          </div>
          <div className="service-card">
            <span className="icon">💳</span>
            <h3>Credit Cards</h3>
            <p>Flexible credit card options with rewards and cashback offers.</p>
          </div>
          <div className="service-card">
            <span className="icon">📈</span>
            <h3>Investment Plans</h3>
            <p>Strategic investment solutions to help you achieve your financial goals.</p>
          </div>
        </div>
      </section>
            <h1>Login</h1>
            <form onSubmit={submit}>
                <input
                    type="email"
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="Email"
                    required
                />
                <input
                    type="password"
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="Password"
                    required
                />
                <input type="submit" value="Login" />
            </form>

            <br />
            <p>OR</p>
            <br />

            <Link to="/signup">Signup Page</Link>
        </div>
    );
}
export default Login;
